% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
n          = 6; % [Input] (1) Size
Q          = eye(n); % [Input] (1) Second matrix (identity)

%% Stage 1
% [EXPLICIT] Hilbert matrix: H_{ij} = \frac{1}{i + j - 1}
H = zeros(n, n);
for i = 1:n
    for j = 1:n
        H(i, j) = 1 / (i + j - 1);
    end
end

%% Stage 2
% [EXPLICIT] Row sums: b_i = \sum_j H_{ij}
b = zeros(n, 1);
for i = 1:n
    s_sum1 = 0;
    for j = 1:n
        s_sum1 = s_sum1 + (H(i, j));
    end
    b(i) = s_sum1;
end
% [EXPLICIT] Product: C_{ij} = \sum_k H_{ik} Q_{kj}
C = zeros(n, n);
for i = 1:n
    for j = 1:n
        s_sum2 = 0;
        for k = 1:n
            s_sum2 = s_sum2 + (H(i, k) * Q(k, j));
        end
        C(i, j) = s_sum2;
    end
end
% [EXPLICIT] Trace: \tau = \sum_i H_{ii}
s_sum3 = 0;
for i = 1:n
    s_sum3 = s_sum3 + (H(i, i));
end
tau = s_sum3;
% [EXPLICIT] Shifted: d_i = \sum_{j=1}^{i} H_{j1}
d = zeros(n, 1);
for i = 1:n
    s_sum4 = 0;
    for j = 1:i
        s_sum4 = s_sum4 + (H(j, 1));
    end
    d(i) = s_sum4;
end

%% Stage 3
% [EXPLICIT] Solve: \mathbf{x} = H^{-1} b
x = (H \ b);

%% Results
fprintf('%-12s = %s\n', 'H', mat2str(H));
fprintf('%-12s = %s\n', 'b', mat2str(b));
fprintf('%-12s = %s\n', 'x', mat2str(x));
fprintf('%-12s = %s\n', 'Q', mat2str(Q));
fprintf('%-12s = %s\n', 'C', mat2str(C));
fprintf('%-12s = %s\n', 'tau', mat2str(tau));
fprintf('%-12s = %s\n', 'd', mat2str(d));
fprintf('%-12s = %s\n', 'n', mat2str(n));